const PROFILE_SCHEMA_VERSION = 3;
const POCKET_ENGINE_AUTO_VERSION = 'v4';

// Answered at most once per device, whichever way the reader answers. See the
// recovery prompt in the profile-load path for why this cannot be inferred.
const ENGINE_DOWNGRADE_RECOVERY_KEY = 'pr_engine_downgrade_recovery_v1';

window.resolveEngineDowngradeRecovery = function resolveEngineDowngradeRecovery(restoreNeural) {
  try { localStorage.setItem(ENGINE_DOWNGRADE_RECOVERY_KEY, restoreNeural ? 'restored' : 'kept-device'); } catch (_) {}
  window.closeFeatureDialog?.();
  if (!restoreNeural) return;
  if (!window.userProfile) window.userProfile = {};
  if (!window.userProfile.settings) window.userProfile.settings = {};
  // 'pocket' is the stored value for BOTH neural engines. Deliberately NOT
  // routed through switchReaderVoiceEngine('pocket'), which would rewrite the
  // narration override and silently move a Kokoro reader onto Pocket. Leaving
  // the override alone restores whichever engine they had actually chosen.
  window.userProfile.settings.voiceEngine = 'pocket';
  window.userProfile.settings._engineManuallySet = true;
  window._pocketNeuralEngineUnavailable = false;
  window.saveLocalData?.();
  window.renderNarrationEngineControls?.();
  try { window.refreshVoiceSelectorForEngine?.(); } catch (_) {}
  window.pocketNotify?.('Neural narration restored.', 5000);
};

// Offer a way back from the persisted automatic downgrade, once, ever.
//
// Until sw v196 a neural worker that failed to load called
// switchReaderVoiceEngine('webspeech') NON-silently, so the downgrade was
// written to the profile AND marked _engineManuallySet -- indistinguishable in
// stored data from a reader who genuinely prefers the device voice. Because
// only a neural engine starts a cache job, every story opened afterwards
// skipped the "Preparing Narration" modal in silence, with nothing on screen
// connecting the two.
//
// The condition asks _resolveActiveEngine rather than reading a settings key,
// because that resolver IS the thing the bug spoke through: it prefers the
// in-memory profile and falls back to the stored one, and its answer is what
// every narration gate in the app actually tests. window._pocketNeuralEngineUnavailable
// is excluded so a failure happening right now -- already explained by the
// companion, already retried on the next reload -- never triggers this.
(function offerEngineDowngradeRecovery() {
  let attempts = 0;
  const attempt = () => {
    if (++attempts > 10) return;
    try {
      if (localStorage.getItem(ENGINE_DOWNGRADE_RECOVERY_KEY)) return;
      if (window._pocketNeuralEngineUnavailable === true) return;
      if (typeof window._resolveActiveEngine !== 'function') return setTimeout(attempt, 1000);
      if (window._resolveActiveEngine() !== 'webspeech') return;
      if (typeof window.showFeatureDialog !== 'function') return setTimeout(attempt, 1000);
    } catch (_) {
      return;
    }
    window.showFeatureDialog(
      'Restore neural narration?',
      '<p>Narration on this device is set to the built-in <strong>Device voice</strong>.</p>'
      + '<p>Earlier versions could switch to it on their own when a neural voice failed to load, '
      + 'and saved that switch as though you had made it — so this may not have been your '
      + 'choice. That fault is fixed.</p>',
      '<button class="pr-btn-primary" onclick="window.resolveEngineDowngradeRecovery(true)">Use neural narration</button>'
      + '<button class="pr-btn-sub" onclick="window.resolveEngineDowngradeRecovery(false)">Keep device voice</button>',
    );
  };
  setTimeout(attempt, 2500);
})();
const WITHDRAWN_TITLE_HASHES = new Set([2097602949, 4010063105, 498652239, 3528427211]);
const WITHDRAWN_AUTHOR_HASHES = new Set([1741912528]);
const WITHDRAWN_FILE_HASHES = new Set([586215127, 4227966908]);

function _profileHash(value) {
  return profileHash(value);
}
window.profileHash = profileHash;
window.storyKeyFor = storyKeyFor;

function _storyFilename(value) {
  const raw = String(value || '');
  if (!raw) return '';
  try {
    const parsed = new URL(raw, window.location.origin);
    const parts = parsed.pathname.split('/').filter(Boolean);
    return parts[parts.length - 1] || raw;
  } catch (_) {
    const parts = raw.split(/[\\/]/).filter(Boolean);
    return parts[parts.length - 1] || raw;
  }
}

function getStoryStableKey(story) {
  return storyKeyFor(story && typeof story === 'object' ? story : {});
}
window.getStoryStableKey = getStoryStableKey;

function findLibraryStoryByRef(ref, library = window.userProfile?.library || []) {
  const value = String(ref || '');
  if (!value) return null;
  const byKey = library.find((story) => (story.storyKey || getStoryStableKey(story)) === value);
  if (byKey) return byKey;
  const titleMatches = library.filter((story) => story.title === value);
  return titleMatches.length === 1 ? titleMatches[0] : null;
}
window.findLibraryStoryByRef = findLibraryStoryByRef;

function isWithdrawnLibraryStory(story) {
  if (!story) return false;
  if (WITHDRAWN_TITLE_HASHES.has(_profileHash(story.title))) return true;
  if (WITHDRAWN_AUTHOR_HASHES.has(_profileHash(story.author || story.creator))) return true;
  const possibleFiles = [
    story.url,
    story.id,
    story.sourceUrl,
    story.source_url,
    story.filename,
    story.file,
  ];
  return possibleFiles.some((value) => value && WITHDRAWN_FILE_HASHES.has(_profileHash(_storyFilename(value))));
}
window.isWithdrawnLibraryStory = isWithdrawnLibraryStory;

const VALID_COMPANIONS = new Set(['virtue', 'none', 'jade']);

function normalizePronunciationOverrides(input) {
  return normalizeTtsPronunciationOverrides(input);
}
window.normalizePronunciationOverrides = normalizePronunciationOverrides;

function normalizeCompanionSetting(profile) {
  if (!profile || typeof profile !== 'object') return;
  const settings = profile.settings || {};
  const raw = String(settings.companion || profile.companion || 'virtue').toLowerCase().trim();
  const companion = VALID_COMPANIONS.has(raw) ? raw : 'virtue';
  settings.companion = companion;
  if (profile.companion !== undefined) profile.companion = companion;
}

function normalizePocketVoiceSetting(profile) {
  const settings = profile?.settings;
  if (!settings || typeof settings !== 'object') return;
  const defaultVoice = window.POCKET_DEFAULT_VOICE || 'donald_malone';
  const voices = window.POCKET_VOICES || [];
  // One-time migration to the default voice (donald_malone). The previous default
  // was 'rayne', and normalizePocketVoiceSetting always writes the
  // resolved default back into settings.pocketVoice. Only migrate profiles that are still on that old
  // default (never a voice the user deliberately picked). Gated by
  // 'pr_voice_migrated_to_donald_malone_v3' on first run.
  if ((settings.pocketVoice === 'rayne' || !settings.pocketVoice)
      && typeof localStorage !== 'undefined'
      && !localStorage.getItem('pr_voice_migrated_to_donald_malone_v3')) {
    settings.pocketVoice = 'donald_malone';
    localStorage.setItem('pr_voice_migrated_to_donald_malone_v3', 'true');
  }
  const canonical = typeof window.canonicalPocketVoice === 'function'
    ? window.canonicalPocketVoice(settings.pocketVoice || defaultVoice)
    : String(settings.pocketVoice || defaultVoice).toLowerCase().trim();
  const baseVoice = voices.includes(canonical)
    ? canonical
    : canonical.replace(/_(neutral|calm|happy|sad|worried|surprised|tired|frustrated|anger|excited|enthused|shout|confused)$/, '');
  settings.pocketVoice = voices.includes(baseVoice) ? baseVoice : defaultVoice;
  if (settings.expressiveProsody === undefined) {
    settings.expressiveProsody = true;
  }
  if (!['neutral', 'balanced', 'expressive'].includes(settings.voiceEmotionMode)) {
    settings.voiceEmotionMode = 'balanced';
  }
  if (settings.pausePunctuation === undefined) settings.pausePunctuation = true;
  if (settings.pauseTags === undefined) settings.pauseTags = true;
  // Explicit booleans so the UI toggles and push-subscription check don't read
  // undefined on profiles that predate these settings. Push stays opt-in (off).
  if (settings.showHints === undefined) settings.showHints = true;
  if (settings.pushUpdates === undefined) settings.pushUpdates = false;
  // Default app text size for new/unset profiles (compact 11pt reads better on
  // phones). Existing users keep whatever they've set.
  if (settings.appFontSize === undefined || settings.appFontSize === null
      || Number.isNaN(Number(settings.appFontSize))) {
    settings.appFontSize = 11;
  }
  if (settings.speed === undefined || settings.speed === null || Number.isNaN(Number(settings.speed))) {
    settings.speed = DEFAULT_POCKET_PLAYBACK_SPEED;
  }
  // Move only the former untouched default to natural 1.0x. The one-time flag
  // prevents a later deliberate 1.08x choice from being silently changed.
  if (!settings._migratedNaturalVoiceSpeed) {
    if (Math.abs(Number(settings.speed) - 1.08) < 0.0001) {
      settings.speed = DEFAULT_POCKET_PLAYBACK_SPEED;
    }
    settings._migratedNaturalVoiceSpeed = true;
  }
  if (!['stable', 'balanced', 'expressive'].includes(settings.pocketTemperaturePreset)) {
    settings.pocketTemperaturePreset = DEFAULT_POCKET_TEMPERATURE_PRESET;
  }
  if (!['mobile', 'quality'].includes(settings.pocketQualityMode)) {
    settings.pocketQualityMode = DEFAULT_POCKET_QUALITY_MODE;
  }
  if (!['auto', 'wasm', 'webgpu'].includes(settings.pocketBackend)) {
    settings.pocketBackend = 'auto';
  }
  settings.pronunciationOverrides = normalizePronunciationOverrides(settings.pronunciationOverrides);
  normalizeCompanionSetting(profile);
}

function normalizeProfileObject(profile) {
  let normalized = profile;
  for (let i = 0; i < 2 && typeof normalized === 'string'; i++) {
    try {
      normalized = JSON.parse(normalized);
    } catch (_) {
      normalized = {};
      break;
    }
  }
  if (!normalized || typeof normalized !== 'object' || Array.isArray(normalized)) normalized = {};
  if (!Array.isArray(normalized.library)) normalized.library = [];
  if (!normalized.settings || typeof normalized.settings !== 'object' || Array.isArray(normalized.settings)) normalized.settings = {};
  normalizePocketVoiceSetting(normalized);
  if (!normalized.stats || typeof normalized.stats !== 'object' || Array.isArray(normalized.stats)) {
    normalized.stats = { totalWords: 0, totalMinutes: 0, finishedStories: 0 };
  }
  if (!normalized.deletedStoryKeys || typeof normalized.deletedStoryKeys !== 'object' || Array.isArray(normalized.deletedStoryKeys)) {
    normalized.deletedStoryKeys = {};
  }
  normalized.schemaVersion = Math.max(Number(normalized.schemaVersion) || 0, PROFILE_SCHEMA_VERSION);
  normalized.library.forEach((story) => {
    if (!story || typeof story !== 'object') return;
    story.storyKey = story.storyKey || getStoryStableKey(story);
    story.updatedAt = story.updatedAt || story.lastRead || story.addedAt || Date.now();
  });
  return typeof window.normalizeProfileV3 === 'function' ? window.normalizeProfileV3(normalized) : normalized;
}
window.normalizeProfileObject = normalizeProfileObject;

function _markDeletedStory(profile, story) {
  if (!profile || !story) return;
  if (!profile.deletedStoryKeys || typeof profile.deletedStoryKeys !== 'object') profile.deletedStoryKeys = {};
  profile.deletedStoryKeys[getStoryStableKey(story)] = Date.now();
}
window.markDeletedStory = _markDeletedStory;

function sanitizeProfileLibrary(profile, options = {}) {
  const target = normalizeProfileObject(profile);
  const before = target.library.length;
  const kept = [];
  target.library.forEach((story) => {
    if (isWithdrawnLibraryStory(story)) {
      _markDeletedStory(target, story);
      if (options.purgeStorage && typeof window._deleteStoryChapters === 'function') {
        Promise.allSettled([
          window._deleteStoryChapters(story.storyKey || getStoryStableKey(story)),
          window._deleteStoryChapters(story.title || ''),
        ]).catch(() => {});
      }
    } else {
      story.storyKey = story.storyKey || getStoryStableKey(story);
      story.updatedAt = story.updatedAt || story.lastRead || story.addedAt || Date.now();
      kept.push(story);
    }
  });
  target.library = kept;
  if (window.currentStory && isWithdrawnLibraryStory(window.currentStory)) {
    window.currentStory = null;
  }
  target.updatedAt = Date.now();
  return before !== kept.length;
}
window.sanitizeProfileLibrary = sanitizeProfileLibrary;

function sanitizeCurrentProfile(options = {}) {
  window.userProfile = normalizeProfileObject(window.userProfile);
  const changed = sanitizeProfileLibrary(window.userProfile, options);
  if (changed && options.save !== false && typeof window.saveLocalData === 'function') {
    window.saveLocalData();
  }
  return changed;
}
window.sanitizeCurrentProfile = sanitizeCurrentProfile;

function mergeProfileIntoCurrent(incomingProfile, options = {}) {
  window.userProfile = normalizeProfileObject(window.userProfile);
  const incoming = normalizeProfileObject(incomingProfile);
  sanitizeProfileLibrary(incoming, { purgeStorage: false });
  sanitizeProfileLibrary(window.userProfile, { purgeStorage: !!options.purgeStorage });

  const localDeleted = window.userProfile.deletedStoryKeys || {};
  const incomingDeleted = incoming.deletedStoryKeys || {};
  window.userProfile.deletedStoryKeys = { ...incomingDeleted, ...localDeleted };
  let merged = false;

  incoming.library.forEach((incomingStory) => {
    const key = incomingStory.storyKey || getStoryStableKey(incomingStory);
    if (window.userProfile.deletedStoryKeys[key]) return;
    const localStory = window.userProfile.library.find((story) => (story.storyKey || getStoryStableKey(story)) === key);
    if (!localStory) {
      incomingStory.storyKey = key;
      window.userProfile.library.push(incomingStory);
      merged = true;
      return;
    }
    const incomingStamp = incomingStory.updatedAt || incomingStory.lastRead || incomingStory.addedAt || 0;
    const localStamp = localStory.updatedAt || localStory.lastRead || localStory.addedAt || 0;
    if (incomingStamp > localStamp) {
      Object.assign(localStory, incomingStory, { storyKey: key });
      merged = true;
    }
  });

  if (incoming.settings) {
    // Resolve settings conflicts by which side was edited most recently, so a
    // change made on another device isn't silently discarded by a blanket
    // "one side always wins" merge (Issue 9). settingsUpdatedAt is stamped only
    // on genuine user edits (see the settings-edit listener in settings_manager
    // and the setup wizard), never on boot-time programmatic writes.
    // localSettingsWin forces the local side to win regardless of timestamps —
    // used when a user logs in right after local setup so their fresh wizard
    // choices aren't overwritten by an older cloud profile.
    // When either side has per-field clocks, merge field-by-field so a newer
    // theme on one device is not wiped by an older wholesale settings blob.
    const localTs = Number(window.userProfile.settingsUpdatedAt) || 0;
    const incomingTs = Number(incoming.settingsUpdatedAt) || 0;
    const localClocks = (window.userProfile.settingsFieldUpdatedAt && typeof window.userProfile.settingsFieldUpdatedAt === 'object')
      ? window.userProfile.settingsFieldUpdatedAt : {};
    const incomingClocks = (incoming.settingsFieldUpdatedAt && typeof incoming.settingsFieldUpdatedAt === 'object')
      ? incoming.settingsFieldUpdatedAt : {};
    const hasFieldClocks = Object.keys(localClocks).length > 0 || Object.keys(incomingClocks).length > 0;
    if (options.localSettingsWin) {
      window.userProfile.settings = { ...incoming.settings, ...window.userProfile.settings };
    } else if (hasFieldClocks) {
      const [mergedSettings, mergedClocks] = mergeClockedMap(
        window.userProfile.settings,
        incoming.settings,
        localClocks,
        incomingClocks,
      );
      window.userProfile.settings = mergedSettings;
      window.userProfile.settingsFieldUpdatedAt = mergedClocks;
    } else {
      const incomingWins = incomingTs > localTs;
      window.userProfile.settings = incomingWins
        ? { ...window.userProfile.settings, ...incoming.settings }
        : { ...incoming.settings, ...window.userProfile.settings };
    }
    window.userProfile.settingsUpdatedAt = Math.max(localTs, incomingTs);
    merged = true;
  }
  if (incoming.stats) window.userProfile.stats = { ...incoming.stats, ...window.userProfile.stats };
  if (incoming.displayName && (!window.userProfile.displayName || window.userProfile.displayName === 'Guest Reader')) {
    window.userProfile.displayName = incoming.displayName;
  }
  sanitizeProfileLibrary(window.userProfile, { purgeStorage: !!options.purgeStorage });
  window.userProfile.updatedAt = Date.now();
  return merged;
}
window.mergeProfileIntoCurrent = mergeProfileIntoCurrent;

function cloneProfileForSync(profile = window.userProfile) {
  if (typeof window.buildSyncPayloadV3 === 'function') return window.buildSyncPayloadV3(profile);
  const clone = JSON.parse(JSON.stringify(normalizeProfileObject(profile)));
  sanitizeProfileLibrary(clone, { purgeStorage: false });
  clone.schemaVersion = PROFILE_SCHEMA_VERSION;
  clone.updatedAt = Date.now();
  if (Array.isArray(clone.library)) clone.library.forEach((story) => { delete story.chapters; });
  delete clone.avatar;
  if (clone.settings) delete clone.settings.siteCookies;
  return clone;
}
window.cloneProfileForSync = cloneProfileForSync;


function _escapeHtml(s) {
  return String(s == null ? "" : s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}
window._escapeHtml = _escapeHtml;

function _safeHttpCoverUrl(value) {
  const raw = String(value || '').trim();
  // new URL('', location) is the document URL, so an empty cover became
  // <img src="https://…/pocket-reader/"> and every tile showed a broken image.
  if (!raw) return '';
  try {
    const parsed = new URL(raw, window.location.href);
    if (parsed.protocol === 'http:' || parsed.protocol === 'https:') return parsed.href;
  } catch (_) {}
  return '';
}

