// ── Curated library seeding ──────────────────────────────────────────────────
// The bundled curated stories appear in every user's library by default at app
// launch. A curated story the user deleted stays deleted (deletedStoryKeys
// tombstone), and withdrawn works are never added.
export async function seedCuratedLibrary() {
  if (window.curatedLibraryLoaded) return;
  if (!window.HF_API_BASE) return;
  // Set the guard before the fetch so overlapping calls (boot + library view
  // during a slow HF cold start) don't kick off duplicate requests.
  window.curatedLibraryLoaded = true;
  const ac = new AbortController();
  const timer = setTimeout(() => ac.abort(), 20000);
  try {
    const r = await fetch(`${window.HF_API_BASE}/api/library/curated`, { signal: ac.signal });
    const data = typeof window._safeParseJson === 'function'
      ? await window._safeParseJson(r, 'API')
      : await r.json();
    if (!data || !Array.isArray(data.items) || data.items.length === 0) return;

    window.userProfile = normalizeProfileObject(window.userProfile);
    const tombstones = window.userProfile.deletedStoryKeys || {};
    let added = false;

    data.items.forEach((item) => {
      if (isWithdrawnLibraryStory(item)) return;
      const key = getStoryStableKey({ sourceUrl: item.source_url, url: item.url, title: item.title, author: item.author });
      // Deletions recorded before the AO3 source-link backfill were keyed by
      // the curated URL instead of the source URL — honor both.
      const legacyKey = getStoryStableKey({ url: item.url, title: item.title, author: item.author });
      if (tombstones[key] || tombstones[legacyKey]) return; // the user deleted this curated story — respect that
      const existing = window.userProfile.library.find(
        (s) => (s.url || s.id) === item.url || (s.storyKey || getStoryStableKey(s)) === key);
      if (existing) {
        // Backfill the AO3 source link onto curated stories added before the
        // backend started reporting it, so "Check for New Chapters" works.
        if (item.source_url && !existing.sourceUrl) {
          existing.sourceUrl = item.source_url;
          added = true;
        }
        // Backfill the curated tag too. Profiles created before this tag
        // existed hold these stories untagged, which would keep counting them
        // toward First Edition and Hoarder and would hide them from the
        // Curated tab. The backend's list is the authority on what is curated.
        if (existing.source !== 'curated') {
          existing.source = 'curated';
          added = true;
        }
        return;
      }
      window.userProfile.library.push({
        id: item.url,
        url: item.url,
        sourceUrl: item.source_url || '',
        title: item.title,
        author: item.author,
        storyKey: key,

        isFinished: false,
        progressChapter: 0,
        progressParagraph: 0,
        addedAt: Date.now(),
        source: 'curated',
      });
      added = true;
    });

    if (sanitizeProfileLibrary(window.userProfile, { purgeStorage: true })) added = true;
    if (added) {
      saveLocalData();
      if (typeof window.renderLibrary === 'function') window.renderLibrary();
      if (typeof window.updateContinueReading === 'function') window.updateContinueReading();
    }
  } catch (err) {
    window.curatedLibraryLoaded = false; // allow a retry (e.g. next library-view visit)
    console.error("Failed to seed curated library", err);
  } finally {
    clearTimeout(timer);
  }
}
window.seedCuratedLibrary = seedCuratedLibrary;

// ── Local profile reset (logout / account switch) ────────────────────────────
// Removes this device's copy of the profile plus all cached story text, audio,
// and the avatar, then rebuilds the default guest profile. Cloud data is
// untouched. preserveSetup keeps the first-time-setup flag so the wizard does
// not reappear.
export async function resetLocalProfile({ preserveSetup = true } = {}) {
  try { localStorage.removeItem('pocketReaderData'); } catch (e) {}
  try { localStorage.removeItem('pr_profile_owner'); } catch (e) {}
  try { sessionStorage.removeItem('pocketReaderCookies'); } catch (e) {}
  try { localStorage.removeItem('pocketReaderCookies'); } catch (e) {}
  await _clearLocalPushIdentity();
  if (!preserveSetup) {
    try { localStorage.removeItem('pr_setup_complete'); } catch (e) {}
  }
  window._cloudPushAllowed = false;
  window.userProfile = _defaultProfile();
  window.currentStory = null;
  window.curatedLibraryLoaded = false;
  if (typeof window._wipeLocalUserData === 'function') {
    try { await window._wipeLocalUserData(); } catch (e) {}
  }
}
window.resetLocalProfile = resetLocalProfile;

async function _clearLocalPushIdentity() {
  let token = '';
  let userId = '';
  try { token = localStorage.getItem('pocketReaderPushAuthToken') || ''; } catch (_) {}
  try { userId = localStorage.getItem('pocketReaderPushUserId') || ''; } catch (_) {}
  try {
    if (token && userId && window.HF_API_BASE) {
      const ac = new AbortController();
      const t = setTimeout(() => ac.abort(), 2000);
      try {
        await fetch(`${window.HF_API_BASE}/api/unsubscribe`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ user_id: userId, auth_token: token }),
          keepalive: true,
          signal: ac.signal,
        });
      } finally {
        clearTimeout(t);
      }
    }
  } catch (_) { /* best-effort; tokens still drop below */ }
  try {
    const reg = await navigator.serviceWorker?.getRegistration?.();
    const sub = await reg?.pushManager?.getSubscription?.();
    await sub?.unsubscribe?.();
  } catch (_) {}
  try { localStorage.removeItem('pocketReaderPushAuthToken'); } catch (_) {}
  try { localStorage.removeItem('pocketReaderPushUserId'); } catch (_) {}
}

export async function loadLocalData() {
  try {
    const savedData = localStorage.getItem('pocketReaderData');
    if (savedData) {
      const parsed = JSON.parse(savedData);
      window.userProfile = { ...window.userProfile, ...parsed };
      window.userProfile = normalizeProfileObject(window.userProfile);
      if (sanitizeProfileLibrary(window.userProfile, { purgeStorage: true })) saveLocalData();

      // Migrate: ensure theme is 'slate' — covers unset (pre-dates the setting) and old default 'dark'
      if (!window.userProfile.settings.theme || window.userProfile.settings.theme === 'dark') {
        window.userProfile.settings.theme = 'slate';
        saveLocalData();
      }

      // Clean up legacy cookies from cloud-syncable profile
      if (window.userProfile.settings.siteCookies) {
        try {
          localStorage.setItem('pocketReaderCookies', JSON.stringify(window.userProfile.settings.siteCookies));
        } catch (e) {}
        delete window.userProfile.settings.siteCookies;
      }

      // NOTE: no cloud push here. Pushing before the profile owner is
      // reconciled with the logged-in account could write this device's data
      // into a different user's cloud row; checkCloudSyncOnStartup pushes
      // after the owner check instead.
    } else {
      // First-time load: build a robust default profile structure to prevent startup crashes
      window.userProfile = _defaultProfile();
    }

    // Load avatar from IndexedDB (prevent localStorage overflow)
    if (window._loadUserAvatar) {
      try {
        const cachedAvatar = await window._loadUserAvatar();
        if (cachedAvatar) {
          window.userProfile.avatar = cachedAvatar;
          const els = ['topbar-avatar-img', 'profile-avatar-img', 'settings-avatar-img'];
          els.forEach((id) => {
            const el = document.getElementById(id);
            if (el) el.src = cachedAvatar;
          });
        }
      } catch (e) {
        console.warn("Failed to load avatar from IndexedDB:", e);
      }
    }

    // ── Voice-engine default (fills a gap; never overrides a choice) ────────
    //
    // This block had never run -- loadLocalData had no caller until the boot
    // hydration was restored -- so enabling it needed its conditions re-checked
    // rather than trusted. One of them was unsafe.
    //
    // It used to ALSO re-run whenever `!_manuallySet && _autoVersion !==
    // POCKET_ENGINE_AUTO_VERSION`, overwriting a stored 'webspeech' with
    // 'pocket'. _engineManuallySet cannot carry the weight that clause put on
    // it, because it is in DEVICE_ONLY_SETTINGS / DEVICE_SETTING_KEYS and is
    // stripped from the sync payload while voiceEngine itself syncs. So a
    // reader who picks Device voice on their phone arrives on their tablet with
    // voiceEngine: 'webspeech' and no flag -- and this would have silently
    // switched them to neural narration there. Verified in a browser: that
    // exact profile shape flipped to 'pocket' and persisted it.
    //
    // The clause bought nothing either way. "Auto-detect" here only ever
    // assigns 'pocket'; the real per-device decision is selectNarrationEngine()
    // inside _resolveActiveEngine, which runs live on every call and picks
    // Kokoro or Pocket from the device profile. So the only thing re-running it
    // could change was somebody's deliberate 'webspeech'.
    //
    // What remains fills a genuinely absent or corrupt value, which is what a
    // default is for.
    const _savedEngine = window.userProfile.settings.voiceEngine;
    const _needsDetect = !_savedEngine || !['pocket', 'webspeech'].includes(_savedEngine);
    if (_needsDetect) {
      window.userProfile.settings.voiceEngine = 'pocket';
      localStorage.setItem('pr_engine_auto_detected', POCKET_ENGINE_AUTO_VERSION);
      console.log(`[AutoDetect] Engine auto-selected: ${window.userProfile.settings.voiceEngine} (cores: ${navigator.hardwareConcurrency}, memory: ${navigator.deviceMemory || '?'}GB, GPU: ${!!navigator.gpu})`);
      if (typeof window.saveLocalData === 'function') window.saveLocalData();
      else saveLocalData();
    }

    // ── Settings UI & display (runs for ALL users) ──────────────────────────
    if (typeof window.initSettingsUI === 'function') window.initSettingsUI();
    if (typeof window.applySettings === 'function') window.applySettings();
    if (typeof window.updateDisplayName === 'function') window.updateDisplayName(window.userProfile.displayName || "Guest Reader");
    if (window.userProfile.avatar) {
      const els = ['topbar-avatar-img', 'profile-avatar-img', 'settings-avatar-img'];
      els.forEach((id) => {
        const el = document.getElementById(id);
        if (el) el.src = window.userProfile.avatar;
      });
    }

    if (typeof window.recordDailyActivity === 'function') window.recordDailyActivity();

    // Narration modules and model initialization are deliberately deferred
    // until the first narration/caching action. Starting them behind onboarding
    // competes with diagnostics and can create avoidable memory pressure.

    // Seed the bundled curated stories into the library at every launch
    // (deleted ones stay deleted via tombstones). Fire-and-forget.
    seedCuratedLibrary();

    // Auto-login sync check
    if (typeof window.checkCloudSyncOnStartup === 'function') {
      window.checkCloudSyncOnStartup();
    }

    // First-time setup modal — checked here so it fires after all async init
    // (avatar load, engine detection, cloud sync) has had a chance to run.
    // Python's init_ui also checks this, but as a fallback only — any exception
    // in the Python init chain would silently skip the check there.
    if (localStorage.getItem('pr_setup_complete') !== 'true') {
      const modal = document.getElementById('first-time-setup-modal');
      if (modal) modal.style.display = 'flex';
    }

  } catch (e) {
    console.error("Failed to load local data:", e);
    localStorage.removeItem('pocketReaderData');
    // Even after a load failure, still show the setup modal for new users
    if (localStorage.getItem('pr_setup_complete') !== 'true') {
      const modal = document.getElementById('first-time-setup-modal');
      if (modal) modal.style.display = 'flex';
    }
  }
}
window.loadLocalData = loadLocalData;

// Read the stored profile back at boot. Nothing did.
//
// loadLocalData() had NO callers anywhere in the repo. Its only caller had been
// FrontEnd_code.py in the Anvil host -- `if hasattr(window, 'loadLocalData'):
// window.loadLocalData()` -- and when the frontend was restructured into
// public/ and Anvil was dropped, the module came across and the boot call did
// not. The migrations inside it commented "runs for ALL users" had therefore
// never run for anyone.
//
// What that cost, measured in a browser: a guest wrote displayName, library and
// settings to pocketReaderData correctly, and after a reload window.userProfile
// was the empty default while the good copy still sat in localStorage,
// unread -- an empty shelf. Worse, the next saveLocalData() (opening a story,
// changing a setting, a playback checkpoint) serialised that empty profile back
// over the stored one, so the library was not merely hidden, it was destroyed a
// moment later.
//
// Signed-in readers were rescued, but not by anything in this file: the startup
// cloud pull lives INSIDE loadLocalData too (checkCloudSyncOnStartup, below), so
// it never ran either. What saved them is that supabase_bridge sets
// _cloudPushAllowed at its own module load on session restore, so the first
// ordinary save round-tripped through the compare-and-swap merge and
// applyCanonicalProfile wrote the cloud library back into memory. The empty
// push did no damage on the way out because mergeProfile only removes stories
// carrying a deletion tombstone. Guests had no such backstop.
//
// The same dead call also meant seedCuratedLibrary(), the avatar restore, the
// theme and voice-engine migrations and the first-run setup check had never run
// on boot for anyone.
//
// Ordering is the whole fix: hydrate before anything can save, and make saving
// impossible until hydration has settled (see _flushLocalData). A failure still
// releases the latch -- the default profile is then genuinely authoritative and
// blocking every future write would be worse than starting fresh.
async function _hydrateLocalProfile() {
  try {
    await loadLocalData();
  } catch (error) {
    console.error('[Profile] Could not read the stored profile:', error);
  } finally {
    _profileHydrated = true;
    if (_saveDeferredDuringHydration) {
      _saveDeferredDuringHydration = false;
      saveLocalData({ immediate: true });
    }
    // loadLocalData refreshes settings and the display name but not the shelf,
    // and the first renderLibrary() has already run against the empty default
    // by the time we get here -- so without this the reader's stories are
    // restored in memory and still invisible on screen.
    try { window.renderLibrary?.(true); } catch (error) { console.warn('[Profile] Library re-render failed:', error); }
    try { window.updateContinueReading?.(); } catch (_) {}
    try { window.renderProfileExtras?.(); } catch (_) {}
  }
}
// Wait for the document to finish parsing before hydrating.
//
// loadLocalData refreshes the UI through initSettingsUI / applySettings /
// updateDisplayName, and all three live in settings_manager.js, which
// index.html loads AFTER this module. Running at module-evaluation time meant
// every one of those typeof guards was false and silently skipped -- the
// profile hydrated correctly but the reader's name still read "Guest Reader"
// and the settings panel still showed defaults. The Anvil host had the same
// requirement and met it by polling until the modules existed.
//
// Module scripts are deferred, so they have all executed by DOMContentLoaded.
// Waiting costs nothing: _flushLocalData refuses to write until the latch
// releases, so no save can clobber the stored profile in the meantime.
// Exposed so a caller that must not race hydration can await it.
window.__pocketProfileHydration = document.readyState === 'loading'
  ? new Promise((resolve) => {
      document.addEventListener('DOMContentLoaded', () => resolve(_hydrateLocalProfile()), { once: true });
    })
  : _hydrateLocalProfile();


// The synchronous write. This is the expensive part (normalize + sanitize +
// full deep clone + JSON.stringify + localStorage write), so it is coalesced by
// saveLocalData()/commitProfileChange() below rather than run on every call.
// Achievement recomputation was moved OUT of here — it is O(library) work that
// only needs to run when the library/stats actually change, not on every
// settings toggle or progress checkpoint (see commitProfileChange).
// A save before the stored profile has been read back is not a save, it is a
// deletion: _flushLocalData serialises whatever is in memory, and until
// hydration finishes that is the empty default. See _hydrateLocalProfile.
let _profileHydrated = false;
let _saveDeferredDuringHydration = false;

function _flushLocalData(options = {}) {
  if (!_profileHydrated) {
    _saveDeferredDuringHydration = true;
    return;
  }
  try {
    window.userProfile = normalizeProfileObject(window.userProfile);
    sanitizeProfileLibrary(window.userProfile, { purgeStorage: false });
    // Strip chapters BEFORE cloning, not after. loadStory() attaches the opened
    // story's full text to its library entry (currentStory IS that entry), and
    // this runs on every playback checkpoint — i.e. once per paragraph. Cloning
    // first meant serialising and re-parsing megabytes of prose on every
    // paragraph purely to delete it on the next line.
    const { library, avatar, ...profileRest } = window.userProfile;
    const liteProfile = JSON.parse(JSON.stringify(profileRest));
    liteProfile.schemaVersion = PROFILE_SCHEMA_VERSION;
    liteProfile.updatedAt = Date.now();
    if (Array.isArray(library)) {
      liteProfile.library = library.map((story) => {
        const { chapters, ...rest } = story;
        const copy = JSON.parse(JSON.stringify(rest));
        copy.storyKey = copy.storyKey || getStoryStableKey(copy);
        copy.updatedAt = copy.updatedAt || copy.lastRead || copy.addedAt || Date.now();
        return copy;
      });
    } else {
      liteProfile.library = [];
    }

    // Persist avatar to IndexedDB instead of localStorage to prevent
    // QuotaExceededError. It is destructured out of the clone above, so it is
    // never serialised here — only handed to the IndexedDB writer.
    if (avatar && window._saveUserAvatar) {
      window._saveUserAvatar(avatar).catch(e => {
        console.error("Failed to save avatar to IndexedDB:", e);
      });
    }

    // Protect sensitive cookies from cloud storage
    if (liteProfile.settings) {
      delete liteProfile.settings.siteCookies;
    }

    localStorage.setItem('pocketReaderData', JSON.stringify(liteProfile));

    // Only push to the cloud once the profile owner has been reconciled with
    // the logged-in account (prevents cross-user writes on shared devices).
    if (!options.skipCloud && window._cloudPushAllowed && !window.userProfile.isSyncing) {
      if (typeof window.queueCloudSync === 'function') window.queueCloudSync('profile-save');
      else if (window.pocketCloud?.saveProfile) window.pocketCloud.saveProfile(liteProfile);
    }
  } catch (e) {
    console.error("saveLocalData failed:", e);
    console.warn("Storage Quota Exceeded. Retrying without avatar/stats, preserving library.");
    try {
      const slim = {
        displayName: window.userProfile.displayName,
        schemaVersion: PROFILE_SCHEMA_VERSION,
        deletedStoryKeys: window.userProfile.deletedStoryKeys || {},
        updatedAt: Date.now(),
        settings: window.userProfile.settings || {},
        library: (window.userProfile.library || []).map((s) => {
          const { chapters, ...rest } = s;
          rest.storyKey = rest.storyKey || getStoryStableKey(rest);
          rest.updatedAt = rest.updatedAt || rest.lastRead || rest.addedAt || Date.now();
          return rest;
        }),
      };
      if (slim.settings) delete slim.settings.siteCookies;
      localStorage.setItem('pocketReaderData', JSON.stringify(slim));
    } catch (e2) {
      console.error("Slim fallback save also failed; leaving existing data intact:", e2);
    }
  }
}

// ── Coalesced profile-commit batch ───────────────────────────────────────────
// A single mutation used to trigger, synchronously and often redundantly: a full
// profile deep-clone + double JSON.stringify (save), an O(library) achievement
// recompute, and a full library-grid innerHTML rebuild — sometimes several times
// in one handler or loop. commitProfileChange() collects those intents and runs
// each at most once per microtask. saveLocalData() routes through it so every
// existing caller is coalesced automatically; pass { immediate:true } to force a
// synchronous write (used right before a reload). A pending write is always
// flushed synchronously on pagehide/hide so nothing is lost if the tab is
// backgrounded or OOM-killed.
let _commitPending = false;
let _commitSave = false;
let _commitSkipCloud = true;
let _commitAchievements = false;
let _commitRenderMode = null;      // null | 'full' | 'card'
let _commitCardKeys = new Set();

function _runCommit() {
  _commitPending = false;
  const doSave = _commitSave;
  const skipCloud = _commitSkipCloud;
  const doAch = _commitAchievements;
  const renderMode = _commitRenderMode;
  const cardKeys = _commitCardKeys;
  _commitSave = false; _commitSkipCloud = true; _commitAchievements = false;
  _commitRenderMode = null; _commitCardKeys = new Set();

  // Achievements first: it can update stats, which the save then persists.
  if (doAch) { try { checkForNewAchievements(); } catch (e) { console.warn('achievement check failed', e); } }
  if (doSave) _flushLocalData({ skipCloud });
  if (renderMode === 'full') { try { renderLibrary(true); } catch (e) { console.warn('renderLibrary failed', e); } }
  else if (renderMode === 'card') { cardKeys.forEach((key) => { try { _updateStoryCardByKey(key); } catch (e) { console.warn('card update failed', e); } }); }
}

export function commitProfileChange(options = {}) {
  if (options.save) { _commitSave = true; if (options.skipCloud !== true) _commitSkipCloud = false; }
  if (options.achievements) _commitAchievements = true;
  if (options.render === 'full') { _commitRenderMode = 'full'; }
  else if (options.render === 'card' && _commitRenderMode !== 'full') {
    _commitRenderMode = 'card';
    const key = options.storyKey
      || (options.title && findLibraryStoryByRef(options.title));
    const resolved = typeof key === 'string' ? key : key && (key.storyKey || getStoryStableKey(key));
    if (resolved) _commitCardKeys.add(resolved);
  }
  if (!_commitPending) { _commitPending = true; queueMicrotask(_runCommit); }
}
window.commitProfileChange = commitProfileChange;

export function saveLocalData(options = {}) {
  if (options.immediate) { _flushLocalData(options); return; }
  commitProfileChange({ save: true, skipCloud: options.skipCloud === true });
}
window.saveLocalData = saveLocalData;

// Replace just one story's card node instead of rebuilding the whole grid.
// Uses the same _buildStoryCardHtml the full render uses, so markup never drifts.
// No-op if the card is not currently shown (e.g. filtered out).
function _updateStoryCardByKey(storyKey) {
  const grid = document.getElementById('library-grid');
  if (!grid || !storyKey) return false;
  const safeKey = (window.CSS && CSS.escape) ? CSS.escape(storyKey) : String(storyKey).replace(/"/g, '\\"');
  const el = grid.querySelector(`[data-story-key="${safeKey}"]`);
  if (!el) return false;
  const story = (window.userProfile?.library || []).find((s) => (s.storyKey || getStoryStableKey(s)) === storyKey);
  if (!story) return false;
  el.outerHTML = _buildStoryCardHtml(story, grid.classList.contains('list-mode'));
  return true;
}

// Flush any pending write synchronously before the page is hidden or unloaded.
function _flushCommitNow() { if (_commitPending) _runCommit(); }
window.addEventListener('pagehide', _flushCommitNow);
window.addEventListener('beforeunload', _flushCommitNow);
document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'hidden') _flushCommitNow(); });

export async function checkCloudSyncOnStartup() {
  if (typeof window.pullCloudProfileOnStartup === 'function') {
    try { await window.pullCloudProfileOnStartup(); } catch (error) { console.error('[CloudSync] Startup sync failed:', error); }
    return;
  }
  if (typeof window.pocketCloud?.getCurrentUser !== 'function') return;
  try {
    const userEmail = await window.pocketCloud.getCurrentUser();
    if (userEmail) {
      console.log("[CloudSync] Auto-logged in on boot:", userEmail);

      // ── Account isolation ────────────────────────────────────────────────
      // pr_profile_owner records which account this device's local profile
      // belongs to. If a DIFFERENT account is now logged in, never merge the
      // previous user's data into it — wipe local state and reboot so the new
      // user starts from their own cloud profile plus the curated defaults.
      const owner = localStorage.getItem('pr_profile_owner') || '';
      if (owner && owner !== userEmail) {
        console.warn("[CloudSync] Logged-in account changed (was", owner, ") — resetting local profile.");
        if (typeof window.resetLocalProfile === 'function') {
          await window.resetLocalProfile({ preserveSetup: true });
        }
        location.reload();
        return;
      }
      localStorage.setItem('pr_profile_owner', userEmail);

      window.userProfile.isLoggedIn = true;
      window.userProfile.cloudEmail = userEmail;

      // Cloud pushes stay DISABLED until the cloud profile has been pulled and
      // merged below. Enabling them here would let a boot-time saveLocalData()
      // (curated seeding, engine-default migration, applySettings, ...) push
      // this device's local-only/default profile over the user's real cloud row
      // before it has even been fetched (Issue 6).

      if (typeof window.pocketCloud?.loadProfile === 'function') {
        const cloudProfile = await window.pocketCloud.loadProfile();
        if (cloudProfile) {
          console.log("[CloudSync] Loaded cloud profile:", cloudProfile);
          const merged = mergeProfileIntoCurrent(cloudProfile, { purgeStorage: true });

          if (merged) {
            console.log("[CloudSync] Merged cloud profile into local profile.");
            // Persist locally only — pushes are still disabled until the merge
            // is fully complete just below.
            if (typeof window.saveLocalData === 'function') window.saveLocalData();
            if (typeof window.renderLibrary === 'function') window.renderLibrary();
            if (typeof window.initSettingsUI === 'function') window.initSettingsUI();
            if (typeof window.applySettings === 'function') window.applySettings();
          }
        }
      }

      // Pull/merge complete — pushes are now safe (Issue 6).
      window._cloudPushAllowed = true;

      // Reflect the (possibly cloud-updated) display name in the topbar, and
      // persist + push the merged profile once via saveLocalData. The cloud
      // email is surfaced on the Profile cloud-sync card, so we no longer stuff
      // it into the display-name slot — that made the name flash the email and
      // then revert to the display name (Issue 8).
      if (typeof window.updateDisplayName === 'function') {
        window.updateDisplayName(window.userProfile.displayName || 'Guest Reader');
      } else if (typeof window.saveLocalData === 'function') {
        window.saveLocalData();
      }

      if (typeof window.renderProfileExtras === 'function') {
        window.renderProfileExtras();
      }
    }
  } catch (e) {
    console.error("[CloudSync] Auto-login check failed:", e);
  }
}
window.checkCloudSyncOnStartup = checkCloudSyncOnStartup;

export function clearTextCache() {
  if (
    confirm(
      "WARNING: This will permanently wipe your entire library, bookmarks, reading progress, custom settings, and all earned achievement progress. This action CANNOT be undone.\n\nAre you absolutely sure you want to proceed and delete all your local data?"
    )
  ) {
    localStorage.removeItem('pocketReaderData');
    localStorage.removeItem('pr_setup_complete');
    localStorage.removeItem('pr_engine_auto_detected');
    localStorage.removeItem('pr_profile_owner');
    window.userProfile = {
      displayName: "Guest Reader",
      library: [],
      settings: {},
      avatar: null,
      stats: {
        totalWords: 0,
        totalMinutes: 0,
        finishedStories: 0,
        hoursListened: 0,
        streak: 0,
        favorites: 0,
        unread: 0,
        firstBookmark: 0,
        firstSleepTimer: 0,
      },
    };
    alert("Text cache and library cleared. Refreshing page.");
    location.reload();
  }
}
window.clearTextCache = clearTextCache;

export function addToLibrary(storyData) {
  if (isWithdrawnLibraryStory(storyData)) {
    if (typeof window.virtueSpeak === 'function') {
      window.virtueSpeak('That story is no longer available in the curated library.', 4500);
    }
    return;
  }
  if (!window.userProfile.library) window.userProfile.library = [];
  const incomingKey = getStoryStableKey(storyData);
  // An explicit (re-)add revokes any earlier deletion tombstone, so the story
  // is not suppressed again by cloud merges or curated seeding.
  if (window.userProfile.deletedStoryKeys && window.userProfile.deletedStoryKeys[incomingKey]) {
    delete window.userProfile.deletedStoryKeys[incomingKey];
  }
  const exists = window.userProfile.library.find((s) => (s.storyKey || getStoryStableKey(s)) === incomingKey);

  // Calculate dynamic words if missing
  let calculatedWords = "-";
  if (Array.isArray(storyData.chapters)) {
    let n = 0;
    storyData.chapters.forEach((ch) => (ch.paragraphs || []).forEach((p) => (n += p.split(/\s+/).filter(Boolean).length)));
    if (n > 0) calculatedWords = n.toLocaleString();
  }

  const finalWords = (storyData.words && storyData.words !== '-' && storyData.words !== '0' && storyData.words !== 0) 
    ? storyData.words 
    : calculatedWords;

  if (!exists) {
    window.userProfile.library.push({
      storyKey: incomingKey,
      title: storyData.title,
      url: storyData.url || "",
      author: storyData.author || "Unknown",
      synopsis: storyData.synopsis || "",
      words: finalWords,
      totalChapters: (Array.isArray(storyData.chapters) && storyData.chapters.length)
        || storyData.totalChapters || 0,
      publishedChapters: (Array.isArray(storyData.chapters) && storyData.chapters.length)
        || storyData.totalChapters || 0,
      declaredChapters: null,
      updateSubscribed: false,
      workComplete: false,
      progressChapter: 0,
      progressParagraph: 0,
      isFinished: false,
      addedAt: Date.now(),
      lastRead: Date.now(),
      updatedAt: Date.now(),
      fandoms: storyData.fandoms || (storyData.fandom ? [storyData.fandom] : []),
      tags: storyData.tags || [],
      coverImage: storyData.coverImage || "",
      favorite: storyData.favorite || false,
      userRating: storyData.userRating || storyData.rating || 0,
    });
    saveLocalData();
  } else {
    exists.lastRead = Date.now();
    exists.updatedAt = Date.now();
    if (!exists.words || exists.words === '-' || exists.words === '0' || exists.words === 0) {
      exists.words = finalWords;
    }
    saveLocalData();
  }
  // Adding a story changes first-story / genres achievement inputs, so recompute
  // achievements here (the save path no longer does it) and do a full re-render.
  commitProfileChange({ achievements: true, render: 'full' });
  updateContinueReading();
}
window.addToLibrary = addToLibrary;

function _isAo3WorkUrl(url) {
  return /^https?:\/\/(?:www\.)?archiveofourown\.org\/works\/\d+/i.test(String(url || ''));
}

function _saveStoryUpdateState(entry) {
  window.stampStorySyncField?.(entry, 'metadata');
  window.saveLocalData?.();
  window.syncPushProfileIfEnabled?.();
  window.queueCloudSync?.('story-update-state');
}

window.toggleStorySubscription = async function(storyRef) {
  const entry = findLibraryStoryByRef(storyRef);
  if (!entry || !_isAo3WorkUrl(entry.sourceUrl || entry.url)) return;
  const sourceUrl = entry.sourceUrl || entry.url;
  let published = Number(entry.publishedChapters || entry.totalChapters || 0);
  let declared = Number(entry.declaredChapters || 0);
  if (!entry.workComplete && !declared && window.HF_API_BASE) {
    try {
      const response = await fetch(`${window.HF_API_BASE}/api/ao3/chapter_count?url=${encodeURIComponent(sourceUrl)}`);
      if (response.ok) {
        const info = await response.json();
        if (typeof info.count === 'number') {
          published = info.count;
          declared = typeof info.total === 'number' ? info.total : 0;
          entry.publishedChapters = published;
          entry.declaredChapters = declared || null;
          entry.workComplete = Boolean(declared && published >= declared);
          _saveStoryUpdateState(entry);
        }
      }
    } catch (_) {}
  }
  if (entry.workComplete || (declared && published >= declared)) {
    window.virtueSpeak?.('This story is complete, so there are no future chapters to follow.', 4000);
    return;
  }
  entry.updateSubscribed = !entry.updateSubscribed;
  _saveStoryUpdateState(entry);
  window.renderLibrary?.(true);
  if (entry.updateSubscribed) {
    window.triggerVirtue?.('virtue_bubble_wink');
    window.virtueSpeak?.('Subscribed. I will let you know when AO3 publishes a new chapter.', 5000);
  } else {
    window.virtueSpeak?.('Story updates are no longer being followed for this work.', 4000);
  }
};

window.checkSubscribedStoryUpdates = async function() {
  if (document.hidden || window.BufferManager?.isActive || window.isPlaying) return;
  const subscribed = (window.userProfile?.library || [])
    .filter((story) => story.updateSubscribed && _isAo3WorkUrl(story.sourceUrl || story.url) && !story.workComplete)
    .slice(0, 3);
  for (const story of subscribed) {
    await window.checkStoryUpdate(story.storyKey || getStoryStableKey(story), story.sourceUrl || story.url, null, { silent: true });
  }
};

window.checkStoryUpdate = async function(storyRef, url, btnElement = null, options = {}) {
  const silent = Boolean(options.silent);
  const announce = (message, duration) => {
    if (!silent && window.virtueSpeak) window.virtueSpeak(message, duration);
  };
  const stage = (asset) => {
    if (!silent && typeof window.triggerVirtue === 'function') window.triggerVirtue(asset);
  };
  const lib = (window.userProfile && window.userProfile.library) || [];
  const entry = findLibraryStoryByRef(storyRef, lib);
  if (!entry) return;
  const title = entry.title;
  const storageRef = entry.storyKey || getStoryStableKey(entry);

  if (!url || !/^https?:\/\//i.test(url)) {
    announce("This story has no source link to check. Use Open File to add a newer version manually.", 6000);
    return;
  }

  let originalBtnHtml = '';
  let card = null;
  if (btnElement) {
    originalBtnHtml = btnElement.innerHTML;
    btnElement.innerHTML = '<span class="global-loading-spinner" style="width:14px; height:14px; border-width:2px; margin:0 8px 0 0; display:inline-block;"></span> Checking...';
    btnElement.disabled = true;
    btnElement.style.opacity = '0.7';
    btnElement.style.cursor = 'wait';

    card = btnElement.closest('.story-card');
    if (card) {
      card.style.opacity = '0.5';
      card.style.transform = 'scale(0.98)';
      card.style.transition = 'all 0.3s ease';
    }
  }

  announce("Checking the source for new chapters...", 4000);
  stage('virtue_thinking');

  try {
    let stored = (await window._loadStoryChapters(storageRef, entry)) || [];
    if (!stored.length && storageRef !== title) {
      stored = (await window._loadStoryChapters(title, entry)) || [];
      if (stored.length) window._saveStoryChapters?.(storageRef, stored, entry).catch(() => {});
    }
    let aoCount = null;
    if (/archiveofourown\.org\/works\/\d+/i.test(url)) {
      try {
        const r = await fetch(`${window.HF_API_BASE}/api/ao3/chapter_count?url=${encodeURIComponent(url)}`);
        if (r.ok) {
          const j = await r.json();
          if (typeof j.count === 'number') {
            aoCount = j.count;
            entry.publishedChapters = j.count;
            entry.declaredChapters = typeof j.total === 'number' ? j.total : null;
        entry.workComplete = entry.declaredChapters !== null && j.count >= entry.declaredChapters;
            _saveStoryUpdateState(entry);
          }
        }
      } catch (e) { }
    }

    const baselineCount = stored.length
      || entry.totalChapters
      || ((window.currentStory && window.currentStory.title === title
           && Array.isArray(window.currentStory.chapters)) ? window.currentStory.chapters.length : 0);

    if (aoCount !== null && baselineCount > 0 && aoCount <= baselineCount) {
      stage('virtue_thinking');
      announce("I checked, but there are no new chapters yet. You're all caught up!", 5000);
      return;
    }

    if (aoCount !== null && baselineCount === 0) {
      entry.totalChapters = aoCount;
      if (typeof window.saveLocalData === 'function') window.saveLocalData();
      stage('virtue_thinking');
      announce("I double-checked the source. No new chapters found.", 5000);
      return;
    }

    const fresh = await window._silentFetchStoryChapters(url);
    if (!fresh || !fresh.length) {
      stage('virtue_thinking');
      announce("Couldn't reach the source to check for updates. Try again in a little while.", 5000);
      return;
    }
    let realFresh = (aoCount !== null && fresh.length > aoCount) ? fresh.slice(0, aoCount) : fresh;
    realFresh = window.normalizeStoryChapters?.(realFresh, entry) || realFresh;

    if (baselineCount === 0) {
      await window._saveStoryChapters(storageRef, realFresh, entry);
      entry.totalChapters = realFresh.length;
      if (typeof window.saveLocalData === 'function') window.saveLocalData();
      if (window.currentStory && window.currentStory.title === title) {
        window.currentStory.chapters = realFresh;
        if (typeof window._buildReaderProgressIndex === 'function') window._buildReaderProgressIndex(window.currentStory);
        if (typeof window.renderChaptersTab === 'function') window.renderChaptersTab();
        if (typeof window.updateReaderUIText === 'function') window.updateReaderUIText();
      }
      if (typeof window.renderLibrary === 'function') window.renderLibrary(true);
      stage('virtue_thinking');
      announce("Library refreshed - no new chapters to add right now.", 4500);
      return;
    }

    if (realFresh.length <= baselineCount) {
      try {
        const freshDirect = await window._silentFetchStoryChapters(url, true);
        if (freshDirect && freshDirect.length > baselineCount) {
          realFresh = window.normalizeStoryChapters?.(freshDirect, entry) || freshDirect;
        } else {
          stage('virtue_thinking');
          announce("I double checked the source. No new chapters found yet.", 4500);
          return;
        }
      } catch (_) {
        stage('virtue_thinking');
        announce("I double checked the source. No new chapters found yet.", 4500);
        return;
      }
    }

    const base = stored.length ? stored : realFresh.slice(0, baselineCount);
    const merged = window.mergeStoryChapters?.(base, realFresh, entry)
      || base.concat(realFresh.slice(base.length));
    const added = Math.max(0, merged.length - base.length);
    if (!added) {
      announce("I checked the latest copy. There are no new chapters yet.", 4500);
      return;
    }
    await window._saveStoryChapters(storageRef, merged, entry);
    if (entry.title && entry.title !== storageRef) {
      window._saveStoryChapters(entry.title, merged, entry).catch(() => {});
    }
    if (entry.url && entry.url !== storageRef) {
      window._saveStoryChapters(entry.url, merged, entry).catch(() => {});
    }
    entry.workComplete = Number(entry.declaredChapters || 0) > 0
      && Number(entry.publishedChapters || 0) >= Number(entry.declaredChapters);
    entry.totalChapters = merged.length;
    entry.publishedChapters = Math.max(Number(entry.publishedChapters || 0), merged.length);
    _saveStoryUpdateState(entry);
    if (typeof window.renderLibrary === 'function') window.renderLibrary(true);
    if (window.currentStory && (window.currentStory.title === title || window.currentStory.storyKey === storageRef)) {
      window.currentStory.chapters = merged;
      window.currentStory.totalChapters = merged.length;
      if (typeof window._buildReaderProgressIndex === 'function') window._buildReaderProgressIndex(window.currentStory);
      else window._readerParaOffsets = null;
      if (typeof window.renderChaptersTab === 'function') window.renderChaptersTab();
      if (typeof window.updateReaderUIText === 'function') window.updateReaderUIText();
    }
    stage('virtue_holding_bubble_happy_no_paws');
    announce(`Found ${added} new chapter${added > 1 ? 's' : ''}! Re-cache to narrate the new part - your existing audio is kept.`, 7000);
  } catch (e) {
    console.error('Story update check failed:', e);
    stage('virtue_annoyed_bubble');
    announce("Update check failed - try again later or use a different source.", 5000);
  } finally {
    if (btnElement) {
      btnElement.innerHTML = originalBtnHtml;
      btnElement.disabled = false;
      btnElement.style.opacity = '1';
      btnElement.style.cursor = 'pointer';
    }
    if (card) {
      card.style.opacity = '1';
      card.style.transform = 'none';
    }
  }
};

export function removeStory(storyRef) {
  const removedStory = findLibraryStoryByRef(storyRef);
  if (!removedStory) return;
  if (!confirm(`Remove "${removedStory.title}" from your library?`)) return;
  const removedKey = removedStory.storyKey || getStoryStableKey(removedStory);
  if (removedStory) {
    _markDeletedStory(window.userProfile, removedStory);
    if (typeof window._deleteStoryChapters === 'function') {
      Promise.allSettled([
        window._deleteStoryChapters(removedKey),
        window._deleteStoryChapters(removedStory.title),
      ]).catch(() => {});
    }
  }
  window.userProfile.library = window.userProfile.library.filter((s) => (s.storyKey || getStoryStableKey(s)) !== removedKey);
  saveLocalData();
  renderLibrary(true);
  updateContinueReading();
  if (typeof window.triggerVirtue === 'function') {
    window.triggerVirtue('virtue_deleted_story');
  }
}
window.removeStory = removeStory;

function _getInitials(title) {
  if (!title) return '?';
  const words = title.replace(/[^a-zA-Z0-9 ]/g, '').split(' ').filter(w => w.length > 0);
  if (words.length === 0) return '?';
  if (words.length === 1) return words[0].substring(0, 2).toUpperCase();
  return words.slice(0, 3).map(w => w[0]).join('').toUpperCase();
}
window._getInitials = _getInitials;

export function toggleLibraryOptions(event, titleSafeId) {
  event.stopPropagation();
  document.querySelectorAll('.lib-options-menu').forEach(m => {
    if (m.id !== 'lib-menu-' + titleSafeId) {
      m.classList.remove('active');
      m.closest('.story-card')?.classList.remove('menu-open');
    }
  });
  const menu = document.getElementById('lib-menu-' + titleSafeId);
  if (menu) {
    menu.classList.toggle('active');
    if (menu.classList.contains('active')) {
      const btn = event.currentTarget;
      if (btn && typeof btn.getBoundingClientRect === 'function') {
        const btnRect = btn.getBoundingClientRect();
        const viewportHeight = window.innerHeight || document.documentElement.clientHeight;
        const spaceBelow = viewportHeight - btnRect.bottom;
        const spaceAbove = btnRect.top;

        // The menu height is around 260px (including hints and rating).
        // Open upward only if space below is tight and space above is larger.
        if (spaceBelow < 260 && spaceAbove > spaceBelow) {
          menu.style.top = 'auto';
          menu.style.bottom = '100%';
          menu.style.marginTop = '0';
          menu.style.marginBottom = '6px';
        } else {
          menu.style.top = '100%';
          menu.style.bottom = 'auto';
          menu.style.marginTop = '4px';
          menu.style.marginBottom = '0';
        }
      } else {
        // Fallback default
        menu.style.top = '100%';
        menu.style.bottom = 'auto';
        menu.style.marginTop = '4px';
        menu.style.marginBottom = '0';
      }

      const menuRect = menu.getBoundingClientRect();
      const mainContent = document.querySelector('.main-content');
      const mainRect = mainContent ? mainContent.getBoundingClientRect() : null;
      const boundaryLeft = mainRect ? mainRect.left + 10 : 10;
      const boundaryRight = mainRect ? mainRect.right - 10 : window.innerWidth - 10;

      let shiftX = 0;
      if (menuRect.left < boundaryLeft) {
        shiftX = boundaryLeft - menuRect.left;
      } else if (menuRect.right > boundaryRight) {
        shiftX = boundaryRight - menuRect.right;
      }
      menu.style.transform = `translateX(${shiftX}px)`;
    }
    menu.closest('.story-card')?.classList.toggle('menu-open', menu.classList.contains('active'));
  }
}
window.toggleLibraryOptions = toggleLibraryOptions;

document.addEventListener('click', () => {
  document.querySelectorAll('.lib-options-menu.active').forEach(m => {
    m.classList.remove('active');
    m.closest('.story-card')?.classList.remove('menu-open');
  });
});

export async function permCacheStory(storyRef) {
  const story = findLibraryStoryByRef(storyRef);
  if (!story) return;
  if(confirm(`Permanent Cache will run in the background to synthesize the entire story. Please leave this page open while it caches.\n\nBegin caching "${story.title}"?`)) {
    await window.startCaching('Permanent', storyRef);
  }
}
window.permCacheStory = permCacheStory;

// Build the HTML for one library card. Extracted so a single-story change
